print(
    """
7) As a next step, we now want to collect all of the multiplication operations.
As mentioned before, these show some repetitions that we can exploit.
We constructed the system in terms of a hierarchical keymap and will now apply
access patterns to them. However, in an abstract perspective, when we multiply the
states entries of (1,2,3) with the hamiltonians entries of (1,2) and consider the results
that we write to (1,2,3) (or shortly: (1,2,3), (1,2) -> (1,2,3)), we are doing exactly the
same thing as we would do with (3,5,7), (3,5) -> (3,5,7), just on different locations in our
keymap.

Let us take one of the operations as an example and pad the pauli string and ignore the phases
for simplification: xxx . zz0 -> yyx takes the first entry (xxx) in the state's (1,2,3), the 3rd
entry (zz, remember, there are only 3 for each pair as defined above) in ham's (1,2) and writes
it to the 13th entry (yyx) in (1,2,3). In (3,5,7), (3,5) -> (3,5,7), we will do exactly the same
steps, but relative to a different starting point in the keymap. We can exploit that by grouping
the operations in the way that their spins overlap in the pattern.

However, be aware that 
a) (1,2,3), (1,3) -> (1,2,3) is *not* just the same set of operations. The spins that share the
   same subspace in the state description as the hamiltonian are differnt. Let us take one of the
   operations as an example and pad the pauli string and ignore the phases for clarification:
   123   12-    123       123   1-3    123
   xxx . zz0 -> yyx while xxx . z0z -> yxy.
b) Pauli strings can cancel each other to identity when multiplied, e.g. xxz . xx0 -> 00z.
   This also means, that (1,2,3), (1,2) can have results in (1,2,3), (1,3), (2,3) and (3,),
   which we will collect in different collections, respectively.
"""
)


multiply_operations = {}
multiply_cases = {}

print(
    """
8) We will now combine every state entry with every hamiltonian entry and remember what we did on
a key and phase level. There is still room for efficiency improvements in this part of the
operation, but that is not the point here.

---------------------------------------------------------------------------------------------

>  for nums_a_key, nums_a_entry in system_keymap.items():
>      for nums_b_key, nums_b_entry in hamilton_keymap.items():
>  
>          for keys_a_key in nums_a_entry.keys():
>              for keys_b_key in nums_b_entry.keys():
>              
>                  ext_string_a = pad_pauli_string(keys_a, nums_a, NUM_SPINS)
>                  ext_string_b = pad_pauli_string(keys_b, nums_b, NUM_SPINS)
>  
>                  ext_prod_c, phase = pauli_mul(ext_string_a, ext_string_b)
>  
>                  multiply_operations[t_pattern][(keys_a, keys_b)].add(
>                      (keys_c, phase)
>                  )

---------------------------------------------------------------------------------------------
"""
)

# we go through the system keymaps first hierarchy level
for nums_a_key, nums_a_entry in system_keymap.items():
    # we get a Key object and the corresponding entry, in this case another keymap as linked
    # before.
    nums_a = nums_a_key.onlylabel()
    # the onlylabel access method makes sure, that the key is not composed from multiple keys
    # in nested maps. If we call system_keymap.items(recursive=True), we will get an error, as
    # the recursive call wants to traverse the keymap all the way to the end, yielding composed
    # keys such as (1,2,3), xxx instead of only (1,2,3).
    # Using onlylabel() is a safety measure
    for nums_b_key, nums_b_entry in hamilton_keymap.items():
        nums_b = nums_b_key.onlylabel()

        # preemtive check: chance to be in truncated subspace
        exp_spinnumbers = set.union(
            set(nums_a_key.onlylabel()), set(nums_b_key.onlylabel())
        )

        # this will save us some work. The hamiltonian is limited to size 2 and the state to
        # MAX_SIZE, as is the result. If the set of all contributing indices is too large, there is
        # no way cancellation to identity can reduce the pauli spin enough to keep it relevant.
        if len(exp_spinnumbers) >= MAX_SIZE + 2:
            continue

        for keys_a_key in nums_a_entry.keys():
            keys_a = keys_a_key.onlylabel()
            ext_string_a = pad_pauli_string(keys_a, nums_a, NUM_SPINS)
            for keys_b_key in nums_b_entry.keys():
                keys_b = keys_b_key.onlylabel()
                ext_string_b = pad_pauli_string(keys_b, nums_b, NUM_SPINS)

                ext_prod_c, phase = pauli_mul(ext_string_a, ext_string_b)

                # the t_pattern helps us to group operations that are equivalent with respect
                # to a base index shift.
                t_pattern = triple_pattern(
                    ext_string_a, ext_string_b, ext_prod_c
                )

                # final validity check - still in truncated subspace?
                if t_pattern[-1].count("X") > MAX_SIZE:
                    continue

                # we now associate the operation to the corresponding suboperation
                # if the t_pattern is new, we initialize the set and dict for collection
                if t_pattern not in multiply_operations:
                    multiply_operations[t_pattern] = {}
                    multiply_cases[t_pattern] = set()

                # have we seen this component combination before in this pattern?
                if (keys_a, keys_b) not in multiply_operations[t_pattern]:
                    multiply_operations[t_pattern][(keys_a, keys_b)] = set()

                # we perform the multiplication
                keys_c, nums_c = simplify_pauli_string(ext_prod_c)

                # we remember the result. The set datattype avoids duplicates.
                multiply_operations[t_pattern][(keys_a, keys_b)].add(
                    (keys_c, phase)
                )
                # remember the combination of spin index groups for the pattern to group the call
                multiply_cases[t_pattern].add((nums_a, nums_b, nums_c))

