print(
    """
11) To keep everyting structured, we collect the operations in the t_patterns and make subroutines
from it. We then call all the subroutines.
These subroutines work on little snippets of the full KeyMap. Therefore, we will also define
InstructionVariables for the inner component keymaps (those that contain xxx, ...). We will need
those in all potential sizes. So we create them now and use them to define the routines that cover
the operations for a t_pattern.


---------------------------------------------------------------------------------------------

>  VarInpRInner[size] = InstructionVariable.new(
>          name=f"rho_inner_{size}", config=inner_keymaps_system[size]
>      )
>  
>  ...
>  
>  for num, (t_pattern, operations) in enumerate(multiply_operations.items()):
>      
>      ...
>      rho_variable = VarInpRInner[len_r]
>      ...
>  
>      for (src1_key, src2_key), operation in operations.items():
>          for tgt_key, iphase in operation:
>              
>              instruction = BiLinearOperationInstruction(
>                  target_variable(tgt_key),
>                  rho_variable(src1_key),
>                  ham_variable(src2_key),
>                  1j**iphase,
>              )


---------------------------------------------------------------------------------------------
"""
)

VarInpRInner = {}
VarInpHInner = {}
VarTargInner = {}

# Input rho goes up to max_size + 1.
# At the same time, the targets can also be restricted to these subspaces
for size in range(MAX_SIZE + 1):
    VarInpRInner[size] = InstructionVariable.new(
        name=f"rho_inner_{size}", config=inner_keymaps_system[size]
    )
    VarTargInner[size] = InstructionVariable.new(
        name=f"res_inner_{size}", config=inner_keymaps_system[size]
    )

# Input ham can contribute to single and pair terms
VarInpHInner[1] = InstructionVariable.new(
    name=f"ham_inner_{size}", config=inner_keymaps_hamilt[1]
)
VarInpHInner[2] = InstructionVariable.new(
    name=f"ham_inner_{size}", config=inner_keymaps_hamilt[2]
)


# As we will later call all auxiliary routines in a summarizing call, we can collect them here
libroutines = {}

instruction_groups = {}
for num, (t_pattern, operations) in enumerate(multiply_operations.items()):
    if SHOW_EXTENDED_OUTPUT:
        print(f"aux routine #{num:03d} will provide routines for {t_pattern}")

    instructions = []

    # understand where we look for rho, ham and res by counting the X's in the t_pattern
    len_r, len_h, len_t = map(lambda x: x.count("X"), t_pattern)

    # we define the local variables
    target_variable = VarTargInner[len_t]
    rho_variable = VarInpRInner[len_r]
    ham_variable = VarInpHInner[len_h]

    # The convenience in the Instruction variables is, that they are callable
    # and will represent an access at an offset. These offsets can be stacked,
    # which will simplify the access patterns even further.

    # for all the operations we want to perform, we remember to do a
    # BiLinearOperationInstruction, which is basically z[l] = a * x[j] * y[k]
    for (src1_key, src2_key), operation in operations.items():
        for tgt_key, iphase in operation:
            if SHOW_EXTENDED_OUTPUT:
                print(
                    f"\t{src1_key} × {src2_key} -> {nice_phase(phase)}{tgt_key}"
                )

            # Here, we create the actual instruction. The Builder will decide, how to turn that
            # into code, the instruction level is completely abstract
            instruction = BiLinearOperationInstruction(
                target_variable(tgt_key),
                rho_variable(src1_key),
                ham_variable(src2_key),
                1j**iphase,
            )
            # we remember the instructions though, because we will call them many times for
            # all the index combinations that match the t_pattern
            instructions.append(instruction)

    instruction_groups[t_pattern] = InstructionGroup(instructions)

print(
    """
12) We have now identified the instructions that perform all component level operations
of a t_pattern. We will now repeat these operations for all the index groups that match the
t_pattern and put everything into a routine. We will end up with one routine per t_pattern
that will include all component operations and already provide the necessary repititions
to repeat the component operations on all the index groups that match the t_pattern.

# ---------------------------------------------------------------------------------------------

>  for num, (t_pattern, cases) in enumerate(multiply_cases.items()):
>      environments = []
>      for rho_nums, ham_nums, res_nums in cases:
>          environments.append(
>              InstructionEnvironment(
>                  {
>                      VarInpRInner[len(rho_nums)]: VarRho(rho_nums),
>                      VarInpHInner[len(ham_nums)]: VarHam(ham_nums),
>                      VarTargInner[len(res_nums)]: VarRes(res_nums),
>                  }
>              )
>          )

# ---------------------------------------------------------------------------------------------
"""
)

for num, (t_pattern, cases) in enumerate(multiply_cases.items()):
    # we will use an Environment Instruction. This instruction will add offsets to  instruction
    # variables. You can read in InstructionEnvironment as 'everything in here will be interpreted
    # as seen from this offset'. Performing the component operations from different offsets means
    # creating an offset environment for all the matching index groups and mapping all these
    # environments on the component operations.
    if SHOW_EXTENDED_OUTPUT:
        print(f"aux routine #{num:03d} will provide routines for {t_pattern}")

    environments = []
    for case in cases:
        rho_nums, ham_nums, res_nums = case
        if SHOW_EXTENDED_OUTPUT:
            print(
                "\t create a local offset environment for the index group",
                rho_nums,
                ham_nums,
                res_nums,
            )
        # we will create an instruction environment and put it to the other environments
        # relevant for the t_pattern
        environments.append(
            InstructionEnvironment(
                {
                    VarInpRInner[len(rho_nums)]: VarRho(rho_nums),
                    VarInpHInner[len(ham_nums)]: VarHam(ham_nums),
                    VarTargInner[len(res_nums)]: VarRes(res_nums),
                }
            )
        )

    # we now want all the instruction environments being applied to the same instruction group (that
    # takes care of the component operations). And that's it! That's everything we need to do to
    # cover one of the t_patterns in our KeyMap configurations
    these_instructions = MapApplyInstruction(
        content=instruction_groups[t_pattern],
        environments=environments,
    )
    # having collected all the environments, we can put it into a routine and give it a telling name
    lr_name = f"multiply_{num:03d}"

    # this is the crucial step: We create a libroutine (that is now in a specific target language)
    # from the instructions we have now created. We can reuse the same instructions in another
    # library and even in another language backend.
    libroutine = my_library.libroutine_from_instructions(
        lr_name,
        these_instructions,
        builder=my_builder,
        lrv_assignments=assignments,
        # container_class=F90KernelContainer,
        container_class=F90RoutineContainer,
    )
    # Note that the assignments tell the building process what variables to associate with the
    # abstract instruction variables

    # we will also add the libroutine to our dictionary, to conveniently call it later
    libroutines[lr_name] = libroutine

print(
    """
13) After all the auxiliary routines have been created, we can now create a collective routine
that calls all the auxiliary routines. We will add the routine to the same library:

---------------------------------------------------------------------------------------------

>  call_collection = InstructionGroup(
>      [CallInstruction(lr) for lr in libroutines.values()],
>  )

>  libroutine_multiply = my_library.libroutine_from_instructions(
>      "multiply",
>      call_collection,
>      builder=my_builder,
>      lrv_assignments=assignments,
>      container_class=F90RoutineContainer,
>  )

---------------------------------------------------------------------------------------------
"""
)

# first we group all the calls into one group
call_collection = InstructionGroup(
    [CallInstruction(lr) for lr in libroutines.values()],
)

libroutine_multiply = my_library.libroutine_from_instructions(
    "multiply",
    call_collection,
    builder=my_builder,
    lrv_assignments=assignments,
    container_class=F90RoutineContainer,
)
print(
    """
14) Note that we use the same assignments here. While we have defined the inner component operations
by instruction variables based on the inner local keymaps, the environment will map the outer
variable at an offset to it, making it the "big" variable with a combined offset. 

Also note that the builder handles how the MapApplyContainer is handled. It is easy to later
implement parallelisation here.
"""
)

print(
    """

15) We finally build the library. Internally, there is a lot going on, but all that needs to be
known is that this step also includes loading of external libraries, defining constants, resolving
dependencies, preparing calls and handling counters and loops.

---------------------------------------------------------------------------------------------

>  my_library.build()

---------------------------------------------------------------------------------------------
"""
)

my_library.build()

print(
    f"The library is now written to '{my_library.filename}'. Open it to see the code generated!"
    ""
)

pauli_library = None

try:
    print("attempt to import... ")
    from plib import pauli_library

except ImportError as exc:
    print("import failed, probably not compiled yet.")

if not pauli_library:
    try:
        print("attempt to compile...")

        ret = subprocess.run(
            "f2py -m plib -c pauli_library.f90 --f90flags='-ffree-line-length-none'",
            shell=True,
            stderr=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
        )
        if ret.returncode != 0:
            raise RuntimeError(
                f"f2py failed compilation with exit code {ret.returncode}"
            )
        else:
            print("compilation finished")

    except RuntimeError as exc:
        print("something went wrong during the compilation:")
        print(exc)
        print("try to compile manually via")
        print(
            "  f2py -m plib -c pauli_library.f90 --f90flags='-ffree-line-length-none'"
        )
        sys.exit(1)

    # let's try the import again.
    try:
        print("attempt to import (again)... ")
        from plib import pauli_library

    except ImportError as exc:
        print("import failed again Try to compile manually via")
        print(
            "  f2py -m plib -c pauli_library.f90 --f90flags='-ffree-line-length-none'"
        )
        print("and try running it again.")
        sys.exit(1)

assert pauli_library is not None

print(
    "Using f2py, we can now import the fortran library back into python and see whats in it:"
)
print(
    """
Next to some constants, we got the auxliliary routines and the multiply routine in the library.
Let's demonstrate, how the generated library is reimported into the python code and call it
with some example data.

---------------------------------------------------------------------------------------------

>  from plib import pauli_library
>  
>  size_rho = len(system_keymap)
>  
>  rho_real = np.zeros(size_rho)
>  rho_imag = np.zeros(size_rho)
>  
>  ...
>  
>  idx_rho_1z = system_keymap.key2off((1,), "z")
>  idx_rho_12yx = system_keymap.key2off((1, 2), "yx")
>  
>  rho_real[idx_rho_1z] = 1
>  rho_real[idx_rho_1x] = 1
>  ham_real[idx_ham_12xx] = 1
>  
>  res_real, res_imag = pauli_library.multiply(
>      rho_real, rho_imag, ham_real, ham_imag
>  )
>  
>  print("x @ 2:", res_real[idx_rho_2x])
>  print("xy @ 12:", res_imag[idx_rho_12yx])

---------------------------------------------------------------------------------------------

"""
)
import numpy as np

size_ham = len(hamilton_keymap)
size_rho = len(system_keymap)
size_res = len(system_keymap)

rho_real = np.zeros(size_rho)
rho_imag = np.zeros(size_rho)
ham_real = np.zeros(size_ham)
ham_imag = np.zeros(size_ham)
res_real = np.zeros(size_res)
res_imag = np.zeros(size_res)

# let's select some specific indices
idx_rho_1x = system_keymap.key2off((1,), "x")
idx_rho_2x = system_keymap.key2off((2,), "x")
idx_rho_1y = system_keymap.key2off((1,), "y")
idx_rho_1z = system_keymap.key2off((1,), "z")

idx_rho_12yx = system_keymap.key2off((1, 2), "yx")

idx_ham_12xx = hamilton_keymap.key2off((1, 2), "xx")

rho_real[idx_rho_1z] = 1
rho_real[idx_rho_1x] = 1
ham_real[idx_ham_12xx] = 1

# x0 * xx should give 0x
# z0 * xx should give i yx

res_real, res_imag = pauli_library.multiply(
    rho_real, rho_imag, ham_real, ham_imag
)

print("x @ 2:", res_real[idx_rho_2x])
print("xy @ 12:", res_imag[idx_rho_12yx])
